[data-mp-modal] {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  align-items: center;
  justify-content: center;
  z-index: 1000;
}
.mp-modal-card {
  position: relative;
  box-sizing: border-box;
  background: #ffffff;
  padding: 32px;
  border-radius: 10px;
  width: 420px;
  max-width: calc(100vw - 32px);
  min-height: autopx;
  text-align: center;
}
@media (max-width: 480px) {
  .mp-modal-card {
    padding: 24px 20px;
  }
}
.mp-modal-card .mp-modal-title {
  font-size: 19px;
  font-weight: 600;
  margin: 0 0 8px;
  color: #111111;
}
.mp-modal-card .mp-modal-subtitle {
  font-size: 14px;
  margin: 0 0 20px;
  color: #111111;
  opacity: 0.75;
}
.mp-modal-card .mp-lang-row {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 8px 0;
}
.mp-modal-card .mp-lang-row .mp-lang-toggle {
  flex: 0 0 calc((50% - 4px) * 0.48);
  min-width: 72px;
  margin: 0;
}
.mp-modal-card .mp-lang-toggle {
  display: block;
  box-sizing: border-box;
  width: 48%;
  margin: 8px auto;
  padding: 10px;
  border: 1px solid #1e5abe;
  border-radius: 6px;
  background: #1e5abe;
  text-decoration: none;
  color: #ffffff;
}
.mp-modal-card .mp-lang-toggle:hover {
  background: #ffffff;
  color: #1e5abe;
}
.mp-modal-close-x {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  font-size: 20px;
  line-height: 1;
  color: #6B7280;
  cursor: pointer;
  border-radius: 6px;
}
.mp-modal-close-x:hover {
  background: rgba(0,0,0,0.05);
}

.mp-revisit-modal {
  position: fixed;
  inset: 0;
  z-index: 2000;
  background: rgba(0,0,0,0.5);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: -apple-system, sans-serif;
}
.mp-revisit-modal-card {
  position: relative;
  background: #ffffff;
  color: #21295c;
  padding: 28px 32px;
  border-radius: 8px;
  max-width: 360px;
  text-align: center;
  box-shadow: 0 8px 30px rgba(0,0,0,0.25);
}
.mp-revisit-close {
  position: absolute;
  top: 8px;
  right: 12px;
  background: none;
  border: none;
  font-size: 20px;
  line-height: 1;
  color: #6b7280;
  cursor: pointer;
}
.mp-revisit-message {
  margin: 0 0 20px;
  font-size: 14px;
}
.mp-revisit-buttons {
  display: flex;
  gap: 10px;
  justify-content: center;
}
.mp-revisit-cancel {
  background: #f7f9fa;
  color: #21295c;
  border: 1px solid #e5e7eb;
  border-radius: 4px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.mp-revisit-confirm {
  background: #21295c;
  color: #ffffff;
  border: none;
  border-radius: 4px;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
